    async function openArtifact(item){if(!item||item.status!=="ready")return;activeArtifact=item;const shell=byId("artifactShell");byId("artifactTitle").textContent=item.title||"作品";byId("artifactMeta").textContent="v"+String(item.version)+" · "+artifactKindLabel(item)+" · "+String(item.sensitivity||"private")+" · sandboxed";byId("artifactLoading").textContent="正在打开经过检查的版本…";byId("artifactLoading").classList.remove("hidden");shell.classList.add("open");shell.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";const frame=byId("artifactFrame");frame.setAttribute("sandbox",item.kind==="interactive_capsule"?"allow-scripts":"");try{let frameUrl;if(isLocalPreview){if(!previewArtifactIds.has(item.artifactId))throw new Error("preview_bundle_missing");frameUrl="/app?preview=1&frame=1&preview_artifact="+encodeURIComponent(item.artifactId)}else{frameUrl="/api/miniapp/artifacts/"+encodeURIComponent(item.artifactId)+"/versions/"+String(item.version)+"/bundle";const response=await fetch(frameUrl,{credentials:"same-origin"});if(!response.ok)throw new Error("bundle_"+response.status);const bundle=await response.text();const hash=await hashText(bundle);if(hash!==item.contentHash)throw new Error("bundle_hash_mismatch");frameUrl+="?frame=1"}if(activeArtifact!==item)return;frame.src=frameUrl}catch(error){byId("artifactLoading").textContent="这个版本无法安全打开："+String(error&&error.message||"unavailable")}}
    function showArtifactConfirm(requestType,payload){const labels={ask_opus:["要把它交给 Opus 吗？","作品只能提出请求，不能直接调用模型。确认后仍会由 Mini App 原生流程创建一条有界请求；Phase A 预览不会真的发送。"],pin:["要固定这个版本吗？","Pin 会在 Memory curation API 接通后开放；作品自身不能修改长期记忆。"],export:["要导出这个作品吗？","导出必须由 Mini App 原生界面生成脱敏副本；iframe 没有下载或文件系统权限。"]};const selected=labels[requestType]||["未知请求已拦截","这个作品请求了未开放的能力。Mini App 没有执行它。"];byId("confirmTitle").textContent=selected[0];byId("confirmCopy").textContent=selected[1]+(payload&&typeof payload==="object"?"":"");byId("artifactConfirm").classList.add("open")}
    async function saveArtifactState(message){if(!activeArtifact||message.revision!==activeArtifact.stateRevision+1)return;let encoded;try{encoded=JSON.stringify(message.value)}catch{return}if(new TextEncoder().encode(encoded).byteLength>16384)return;if(isLocalPreview){activeArtifact.stateRevision=message.revision;return}const response=await fetch("/api/miniapp/artifacts/"+encodeURIComponent(activeArtifact.artifactId)+"/versions/"+String(activeArtifact.version)+"/state",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json","x-miniapp-csrf":String(state.csrfToken||"")},body:JSON.stringify({revision:message.revision,value:message.value})});if(response.ok)activeArtifact.stateRevision=message.revision}
    window.addEventListener("message",(event)=>{const frame=byId("artifactFrame");const message=event.data;if(!activeArtifact||event.source!==frame.contentWindow||!message||typeof message!=="object"||Array.isArray(message))return;if(message.artifactId!==activeArtifact.artifactId||message.version!==activeArtifact.version)return;if(message.type==="artifact.ready"){byId("artifactLoading").classList.add("hidden");return}if(message.type==="artifact.resize"){const height=Number(message.height);if(Number.isFinite(height)&&height>=240&&height<=4096)frame.dataset.contentHeight=String(Math.round(height));return}if(message.type==="artifact.state.save"){void saveArtifactState(message);return}if(message.type==="artifact.request"&&["ask_opus","pin","export"].includes(message.requestType)){let bytes=Infinity;try{bytes=new TextEncoder().encode(JSON.stringify(message.payload)).byteLength}catch{}if(bytes<=16384)showArtifactConfirm(message.requestType,message.payload)}});
    async function pollArtifacts(){if(isLocalPreview||!state||!state.artifacts||!state.artifacts.enabled||document.visibilityState!=="visible")return;try{const after=artifactPollAfter||state.artifacts.observedAt||state.observedAt;const response=await fetch("/api/miniapp/artifacts?after="+encodeURIComponent(after),{credentials:"same-origin"});if(!response.ok)return;const update=await response.json();artifactPollAfter=update.observedAt||new Date().toISOString();const incoming=Array.isArray(update.artifacts)?update.artifacts:[];if(incoming.length){const existing=new Map((state.artifacts.items||[]).map((item)=>[item.artifactId,item]));incoming.forEach((item)=>existing.set(item.artifactId,item));state.artifacts.items=Array.from(existing.values()).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));renderToday(state)}if(update.autoOpenArtifactId&&!activeArtifact){const target=(state.artifacts.items||[]).find((item)=>item.artifactId===update.autoOpenArtifactId);if(target)void openArtifact(target)}}catch{}}
